def _chars(unit: str, items: list[tuple[str, int]]) -> CharacterStats:
    total = sum(count for _, count in items)
    usages = [CharacterUsage(character=name, usage_pct=100 * count / total, count=count) for name, count in items]
    return CharacterStats(unit=unit, total=total, characters=usages)


def _stages(items: list[tuple[str, int]]) -> StageStats:
    total = sum(games for _, games in items)
    stages = [StageUsage(stage=name, usage_pct=100 * games / total, games=games) for name, games in items]
    return StageStats(games=total, stages=stages)


def _usage() -> PlayerUsage:
    event = EventCharacters(
        date=dt.date(2026, 11, 1),
        tournament="Weekly",
        event="Singles",
        online=True,
        url="https://www.start.gg/tournament/weekly/event/singles",
        characters=[EventCharacter(character="Little Mac", games=5), EventCharacter(character="Nobody", games=1)],
    )
    many = [("Little Mac", 60), ("Cloud", 15), ("Pac-Man", 9), ("Steve", 6), ("Sonic", 4), ("Lucas", 3), ("Ness", 3)]
    return PlayerUsage(
        lookup=PlayerLookup(query="mac", match_type="tag_exact", player_id=1, tag="Mac", num_events=12),
        window=UsageWindow(
            requests=1,
            events=4,
            sets=40,
            games=100,
            first_date=dt.date(2026, 6, 1),
            last_date=dt.date(2026, 11, 1),
        ),
        recent=_chars("games", many),
        game_1=_chars("games", [("Lucas", 10)]),
        last_events=RecentEvents(
            first_date=event.date,
            last_date=event.date,
            characters=_chars("events", [("Little Mac", 1)]),
            events=[event],
        ),
        starters=_stages([("Pokemon Stadium 2", 3), ("Battlefield", 1)]),
        counterpicks=StageStats(games=0, stages=[]),
        taken_to=_stages([("Battlefield", 2)]),
        switches=Switches(
            sets=30,
            sets_with_switch=4,
            chances_after_losing=20,
            switched_after_losing=3,
            chances_after_winning=40,
            switched_after_winning=1,
        ),
    )


def test_registry_is_consistent():
    kinds = [widget.kind for widget in WIDGETS]
    assert len(kinds) == len(set(kinds))
    assert [widget.form for widget in ADDABLE] == [form for form in TOOL_FORMS if form in [w.form for w in ADDABLE]]
    for widget in WIDGETS:
        assert widget_of(widget.kind) is widget
        assert (widget.form is None) == (widget.tool is None)
        if widget.addable:
            assert widget.form is not None
    assert widget_of("nope") is None


def test_addable_needs_a_tool():
    with pytest.raises(ValueError, match="addable needs a tool"):
        Widget("x", "X", addable=True)


def test_usage_widget_attributes():
    usage = widget_of("usage")
    assert (usage.addable, usage.chat_open) == (True, True)
    assert not widget_of("videos").chat_open
    assert form_for(_usage()) is usage.form
    assert [field.name for field in usage.form.fields({})] == ["player", "vs_characters", "setting", "sets"]
    setting, sets = usage.form.fields({})[-2:]
    assert (setting.kind, setting.value, setting.options) == ("select", "all", ["all", "offline", "online"])
    # how much data: a select of whole requests' worth of sets
    assert (sets.kind, sets.value, sets.options) == ("select", "30", ["30", "60", "90", "120", "150"])
    # the form submits text; the tool gets the number its Literal wants
    assert usage.form.arguments({"player": "Sparg0", "sets": "60"})["sets"] == 60
    assert usage.form.arguments({"player": "Sparg0", "sets": ""})["sets"] == 30
    # vs_characters is typed list[CharGroup], so the form draws the choice input, several picks
    picker = usage.form.fields({"vs_characters": "steve,pac_man"})[1]
    assert (picker.kind, picker.multiple, picker.value) == ("choice", True, "steve,pac_man")
    assert len(picker.choices) == len(CharGroup)
    assert picker.choices[0] == {
        "value": "banjo_and_kazooie",
        "label": "Banjo & Kazooie",
        "icon": "char_icons/banjo_and_kazooie.png",
    }
    # the tool's own inputs (a list of CharGroup) show the same way
    assert usage.form.fields({"vs_characters": [CharGroup.STEVE]})[1].value == "steve"
    assert usage.form.fields({})[1].value == ""
    picked = usage.form.arguments({"player": "Mac", "vs_characters": "pyra_mythra,steve"})["vs_characters"]
    assert picked == [CharGroup.PYRA_MYTHRA, CharGroup.STEVE]
    assert usage.form.arguments({"player": "Mac", "vs_characters": ""})["vs_characters"] is None
    with pytest.raises(ValueError, match="vs_characters"):
        usage.form.arguments({"player": "Mac", "vs_characters": "steve,Goku"})
    # match videos: one character per side, so the same input with one pick each
    videos = widget_of("videos").form.pickers
    assert {name: picker.multiple for name, picker in videos.items()} == {"char_1": False, "char_2": False}
    assert videos["char_1"].options == usage.form.pickers["vs_characters"].options
    # a select left out of the inputs keeps the tool's default (it has no empty choice)
    assert usage.form.arguments({"player": "Mac"})["setting"] == "all"
    assert usage.form.arguments({"player": "Mac", "setting": "offline"})["setting"] == "offline"


def test_usage_view_data(monkeypatch):
    pytest.importorskip("reflex")
    # importing the app links its editor assets into ./assets: keep that in the app's folder
    monkeypatch.chdir(APP_DIR)
    from reflex_kernel.render import MAX_BAR_ROWS, Ui, apply_event, rerun_inputs, to_view

    view = to_view(_usage())
    assert (view.kind, view.summary) == ("usage", "Mac")
    assert view.note == "Mac · 2026-06-01 to 2026-11-01 · newest 40 sets from 4 events, 100 games"

    ui = Ui()
    data = view.data("tab:r1", ui)
    assert [window["key"] for window in data.windows] == ["recent", "game_1", "last_events"]
    assert [window["key"] for window in data.windows if window["on"]] == ["recent"]
    rows = data.chars.rows
    # 7 characters: the first MAX_BAR_ROWS - 1, then the rest folded into one row
    assert len(rows) == MAX_BAR_ROWS
    assert (rows[0].label, rows[0].value, rows[0].width) == ("Little Mac", "60%", "60.0%")
    assert rows[0].icon.endswith("/char_icons/little_mac.png")
    assert rows[2].icon.endswith("/char_icons/pac_man.png")
    assert (rows[-1].label, rows[-1].value, rows[-1].icon) == ("2 others", "6%", "")
    assert "Lucas" in rows[-1].tip
    assert data.chars.note == "100 games"

    groups = [(group.title, len(group.rows)) for group in data.stage_groups]
    assert groups == [("Starters", 2), ("Counterpicks", 0), ("Taken to", 1)]
    assert (data.stage_groups[0].rows[0].label, data.stage_groups[0].rows[0].value) == ("Pokemon Stadium 2", "75%")
    assert data.switch_note == (
        "Changed character in 4 of 30 sets · 3 of 20 games after dropping one · 1 of 40 after taking one"
    )

    assert [icon["name"] for icon in data.events[0].icons] == ["Little Mac (5 games)", "Nobody (1 game)"]
    assert data.events[0].icons[1]["url"] == ""  # an unknown name: shown as text
    assert data.events[0].where == "online"
    assert data.events[0].url == "https://www.start.gg/tournament/weekly/event/singles"
    assert [(s["key"], s["on"]) for s in data.settings] == [("all", "1"), ("offline", ""), ("online", "")]

    # Offline / Online ask the tool again for the same player; the setting shown doesn't
    assert rerun_inputs(view, "setting", "offline") == {
        "player": "mac",
        "vs_characters": "",
        "setting": "offline",
        "sets": "30",
    }
    assert rerun_inputs(view, "setting", "all") is None
    assert rerun_inputs(view, "setting", "nope") is None
    assert rerun_inputs(view, "window", "game_1") is None
    offline = to_view(_usage().model_copy(update={"setting": "offline"}))
    assert offline.note == "Mac · offline only · 2026-06-01 to 2026-11-01 · newest 40 sets from 4 events, 100 games"
    assert [s["key"] for s in offline.data("tab:r1", Ui()).settings if s["on"]] == ["offline"]

    apply_event(view, ui, "window", "game_1")
    data = view.data("tab:r1", ui)
    assert [row.label for row in data.chars.rows] == ["Lucas"]
    assert data.chars.note == "10 games"


class _Speed(Enum):
    SLOW = "slow"
    FAST = "fast"


def _every_kind(  # one parameter per kind of input the form builds from a type
    fighters: list[CharGroup] | None = None,
    rounds: list[Literal[1, 2, 3]] | None = None,
    speeds: list[_Speed] | None = None,
    tags: list[str] | None = None,
    main: CharGroup | None = None,
) -> str:
    """A made-up tool, to check the form follows the types, not the parameter names"""
    return repr((fighters, rounds, speeds, tags, main))


def test_the_form_follows_the_parameter_types():
    form = ToolForm("Every kind", _every_kind)
    fields = {field.name: field for field in form.fields({})}
    # list[<a fixed set>] -> the choice input with several picks, whatever the set is; one
    # character -> the same input with one pick
    assert {name: (f.kind, f.multiple) for name, f in fields.items()} == {
        "fighters": ("choice", True),
        "rounds": ("choice", True),
        "speeds": ("choice", True),
        "tags": ("text", False),  # a list of free text has no options to pick from
        "main": ("choice", False),
    }
    # a search box for a long list only, whether it takes one pick or several
    assert (fields["fighters"].search, fields["main"].search, fields["rounds"].search) == (True, True, False)
    assert fields["rounds"].choices == [{"value": str(n), "label": str(n), "icon": ""} for n in (1, 2, 3)]
    assert [c["value"] for c in fields["speeds"].choices] == ["slow", "fast"]
    # submitted text comes back as the typed values each list wants
    got = form.arguments({"fighters": "steve", "rounds": "3,1", "speeds": "fast"})
    assert (got["fighters"], got["rounds"], got["speeds"]) == ([CharGroup.STEVE], [3, 1], [_Speed.FAST])
    with pytest.raises(ValueError, match="rounds"):
        form.arguments({"rounds": "4"})
    # a single character: one value in, one value out (not a list)
    picker = form.fields({"main": CharGroup.POKEMON_TRAINER})[-1]
    assert picker.value == "pokemon_trainer"
    assert form.arguments({"main": "pyra_mythra"})["main"] is CharGroup.PYRA_MYTHRA
    assert form.arguments({"main": ""})["main"] is None
    with pytest.raises(ValueError, match="main"):
        form.arguments({"main": "Goku"})
